/**
 * TagInput 滚动相关逻辑
 * 当标签数量过多时，输入框显示不下则需要滚动查看
 */
/** 根据根元素查找滚动容器 .{classPrefix}-input__prefix */
export declare function getScrollContainer(root: HTMLElement, classPrefix: string): HTMLElement | null;
/** 计算元素的最大可滚动距离 scrollWidth - clientWidth */
export declare function getScrollDistance(el: HTMLElement): number;
/** 设置/移除 scrollable 状态类，控制 overflow 是否开放 */
export declare function setScrollableClass(el: HTMLElement, classPrefix: string, scrollable: boolean): void;
/** 处理滚轮事件：MAC deltaX / Windows deltaY 兼容 */
export declare function handleWheelScroll(el: HTMLElement, e: {
    deltaX: number;
    deltaY: number;
}): void;
/** 滚动到最左侧并移除 scrollable class（鼠标离开时） */
export declare function scrollToLeft(el: HTMLElement, classPrefix: string): void;
/** 滚动到最右侧并开启 scrollable class */
export declare function scrollToRight(el: HTMLElement, classPrefix: string): void;
